mapper.select:
SELECT ミーティング番号 AS "meetingNumber.value", 件名 AS "subject.value", 開催日 AS "meetingDate.value", TO_TIMESTAMP( CONCAT(TO_CHAR(開催日, 'YYYY-MM-DD'), ' ', 開始時刻), 'YYYY-MM-DD HH24:MI') AS "startTime.value", TO_TIMESTAMP( CONCAT(TO_CHAR(開催日, 'YYYY-MM-DD'), ' ', 開始時刻), 'YYYY-MM-DD HH24:MI') + TO_CHAR(会議時間, '99" minutes"')::INTERVAL AS "endTime.value" FROM (SELECT ミーティング.ミーティング番号, ミーティング.件名, 日程.開催日, CONCAT(TO_CHAR(日程.開始時間,'00'), ':', TRIM(TO_CHAR(日程.開始分,'00'))) AS 開始時刻, 日程.会議時間 FROM ミーティング._ミーティング AS ミーティング INNER JOIN 主催者._ミーティングと主催者 AS ミーティングと主催者 ON ミーティングと主催者.ミーティング番号 = ミーティング.ミーティング番号 INNER JOIN 日程候補._日程 AS 日程 ON 日程.ミーティング番号 = ミーティング.ミーティング番号 LEFT JOIN ミーティング._ミーティングメモ AS ミーティングメモ ON ミーティングメモ.ミーティング番号 = ミーティング.ミーティング番号 WHERE ミーティングと主催者.主催者番号 = #{organizerNumber.value} AND 日程.開催日 BETWEEN #{startDate.value} AND #{endDate.value}
AND (ミーティング.件名 LIKE #{keywordCondition} OR ミーティングメモ.メモ LIKE #{keywordCondition})
) AS ミーティング一覧 ORDER BY ミーティング番号, 開催日, 開始時刻, 会議時間 LIMIT #{limitCount.value}
